// 12-hour clock, BCD-encoded (hours are 1-12, not 0-23).
module TopModule(input clk, input reset, input ena, output pm,
                  output reg [7:0] hh, output reg [7:0] mm, output reg [7:0] ss);
    reg [3:0] hours10, hours1;
    reg [3:0] minutes10, minutes1;
    reg [3:0] seconds10, seconds1;
    reg ampm;
    always @(posedge clk) begin
        if (reset) begin
            hours10 <= 4'd1; hours1 <= 4'd2;
            minutes10 <= 4'd0; minutes1 <= 4'd0;
            seconds10 <= 4'd0; seconds1 <= 4'd0;
            ampm <= 1'b0;
        end else if (ena) begin
            // Increment seconds.
            seconds10 <= 4'd0; seconds1 <= seconds1 + 1;
            if (seconds1 == 4'd10) begin seconds10 <= 4'd1; seconds1 <= 4'd0; end
            // If it's the 12th second, increment minutes.
            if (seconds10 == 4'd1 && seconds1 == 4'd0) begin
                minutes10 <= 4'd0; minutes1 <= minutes1 + 1;
                if (minutes1 == 4'd10) begin minutes10 <= 4'd1; minutes1 <= 4'd0; end
            end
            // If it's the 12th minute, increment hours.
            if (minutes10 == 4'd1 && minutes1 == 4'd0) begin
                hours10 <= 4'd1; hours1 <= hours1 + 1;
                if (hours1 == 4'd13) begin hours10 <= 4'd2; hours1 <= 4'd0; end
                // AM/PM flip.
                ampm <= ~ampm;
            end
        end
    end
    assign pm = ampm;
    assign hh = {hours10, hours1};
    assign mm = {minutes10, minutes1};
    assign ss = {seconds10, seconds1};
endmodule

