// Binary-coded decimal (BCD) incrementer. Increments on every clock
// cycle, rolls over at 10 (0xA), equivalent to a base-10 counter.
module BCDinc (input clk, input reset, input [3:0] din, output [3:0] dout);
    reg [3:0] q;
    always @(posedge clk) begin
        if (reset) q <= 4'd0;
        else if (q == 4'd9) q <= 4'd0;
        else q <= q + 4'd1;
    end
    assign dout = (q == din) ? 4'd0 : (q + 4'd1);
endmodule

